//! Default-off byte-only base Text campaign table inspection; no live-language or timer authority.
use anyhow::{ensure,Context,Result};
use sha2::{Digest,Sha256};
use super::{native_resources::BytePin,resource_cipher};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub(crate) enum Namespace{OriginalBaseText,LitoLtText}
#[derive(Clone,Debug)]pub(crate) struct Provenance{pub record_index:usize,pub member:String,pub offset:usize,pub raw_pin:BytePin,pub decoded_pin:BytePin}
pub(crate) struct Table{pub rows:Vec<Vec<u8>>,pub provenance:Provenance}
#[derive(Debug,PartialEq,Eq)]pub(crate) struct Fields{pub count:usize,pub cycle_seconds:i32,pub lead_seconds:i32,pub message_count:i32,pub secondary_seconds:i32,pub finish_delay_ms:u32,pub start_delay_ms:u32,pub secondary_delay_ms:u32,pub initializer_divisor:i32}
fn pin(bytes:&[u8])->BytePin{BytePin{bytes:bytes.len() as u64,sha256:Sha256::digest(bytes).into()}}
fn integer(bytes:&[u8])->Result<i32>{ensure!(!bytes.is_empty()&&bytes.iter().all(u8::is_ascii_digit),"Only source-observed canonical unsigned ASCII numeric field supported");Ok(std::str::from_utf8(bytes)?.parse()?) }
fn parse(bytes:&[u8])->Result<Vec<Vec<u8>>>{
 ensure!(!bytes.is_empty()&&bytes.len()<=8*1024&&!bytes.contains(&0)&&bytes.last()==Some(&b'\n'),"Table size/NUL/unterminated reader branch unknown");let mut lines=bytes.split(|v|*v==b'\n').map(|v|v.iter().copied().filter(|b|*b!=b'\r').collect::<Vec<_>>());let header=lines.next().context("Header absent")?;let count=usize::try_from(integer(&header)?)?;ensure!(count>0&&count<0x8000,"440770 count bound");let mut rows=vec![None;count];
 for line in lines{ensure!(line.len()<255,"42E8F0 line truncation branch unqualified");if line.is_empty(){continue;}let end=line.iter().position(|v|*v==b' ').context("Canonical index delimiter absent")?;let index=usize::try_from(integer(&line[..end])?)?;ensure!(index<count&&!line[end+1..].is_empty()&&rows[index].is_none(),"Out-of-range/empty/duplicate row unqualified");rows[index]=Some(line[end+1..].to_vec());}
 rows.into_iter().map(|v|v.context("Sparse allocation/uninitialized string branch unqualified")).collect()
}
pub(crate) fn language(code:u32)->u8{match code{932=>b'j',936=>b'h',949=>b'k',950=>b'c',_=>b'e'}}
pub(crate) fn campaign_gate(flag64b6dc:bool,code:u32)->bool{!flag64b6dc&&matches!(code,949|1252)}
pub(crate) fn inspect(enabled:bool,namespace:Namespace,index:&[u8],pak:&[u8],index_pin:BytePin,pak_pin:BytePin,member:&str)->Result<Table>{
 ensure!(enabled&&namespace==Namespace::OriginalBaseText,"Campaign inspection disabled or wrong base647980 namespace");ensure!(index.len()>=4&&index.len()<=8*1024*1024&&pak.len()<=64*1024*1024&&pin(index)==index_pin&&pin(pak)==pak_pin,"Archive pin/budget mismatch");ensure!(matches!(member.to_ascii_lowercase().as_str(),"campaigndesc-c.tbl"|"campaigndesc-e.tbl"|"campaigndesc-h.tbl"|"campaigndesc-j.tbl"|"campaigndesc-k.tbl"),"Exact campaign member required");let count=u32::from_le_bytes(index[..4].try_into()?) as usize;ensure!(count>0&&count<=100000&&index.len()==4+count*28,"Exact bounded old28 index required");let mut decoded=index.to_vec();resource_cipher::decode_payload_in_place(&mut decoded[4..]);let mut selected=None;
 for(i,row)in decoded[4..].chunks_exact(28).enumerate(){let name=&row[4..24];let end=name.iter().position(|v|*v==0).unwrap_or(20);let name=std::str::from_utf8(&name[..end])?;let offset=u32::from_le_bytes(row[..4].try_into()?) as usize;let len=u32::from_le_bytes(row[24..].try_into()?) as usize;let limit=offset.checked_add(len).context("Member overflow")?;ensure!(len<=8*1024*1024&&limit<=pak.len(),"Member range invalid");if name.eq_ignore_ascii_case(member){ensure!(selected.is_none()&&len>0,"Campaign absent/duplicate/empty ambiguity");selected=Some((i,name.to_owned(),offset,limit));}}
 let(record_index,member,offset,end)=selected.context("Campaign member absent")?;let raw=&pak[offset..end];let raw_pin=pin(raw);let mut bytes=raw.to_vec();resource_cipher::decode_payload_in_place(&mut bytes);let decoded_pin=pin(&bytes);let rows=parse(&bytes)?;Ok(Table{rows,provenance:Provenance{record_index,member,offset,raw_pin,decoded_pin}})
}
impl Table{pub(crate) fn source_fields(&self)->Result<Fields>{let cycle=integer(self.rows.first().context("Index0 absent")?)?;let lead=integer(self.rows.get(1).context("Index1 absent")?)?;let message_count=integer(self.rows.get(4).context("Index4 absent")?)?;let selected=usize::try_from(message_count)?.checked_add(5).context("Secondary index overflow")?;let secondary=integer(self.rows.get(selected).context("Index4+5 pointer bound unknown")?)?;let millis=|v:i32|->Result<u32>{Ok(u32::try_from(v)?.checked_mul(1000).context("Source x1000 arithmetic outside qualified nonwrapping range")?)};let divisor=i32::try_from(self.rows.len())?.checked_sub(message_count).and_then(|v|v.checked_sub(7)).context("Initializer divisor arithmetic")?;ensure!(divisor>0,"Initializer idiv divisor unqualified");Ok(Fields{count:self.rows.len(),cycle_seconds:cycle,lead_seconds:lead,message_count,secondary_seconds:secondary,finish_delay_ms:millis(lead)?,start_delay_ms:millis(cycle.checked_sub(lead).context("Negative finish/start interval")?)?,secondary_delay_ms:millis(secondary)?,initializer_divisor:divisor})}}
#[cfg(test)]#[path="native_campaign_resource_study_tests.rs"]mod tests;
